rollback.sql:
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
          FROM modeling_model_release_candidate
         WHERE status <> 'STALE'
           AND status IN ('PUBLISHING', 'PARTIAL', 'PUBLISHED', 'ROLLED_BACK')
           AND (submitted_date IS NULL OR approved_date IS NULL)
    ) THEN
        RAISE EXCEPTION 'ROLLBACK_BLOCKED_MODEL_RELEASE_SELF_SERVICE_AUDIT_EXISTS';
    END IF;
END $$;
